#!/usr/bin/env bash
#
# LIM Digital Platform — Setup Wizard
# Walks through all manual steps to configure .env and GitHub secrets.
# Generated by the /wizard skill. Do not edit the library above STAGES marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=0
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
err()  { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'" line
  line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//$sq/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'" 
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# ── Stage 1: Database (Neon / PostgreSQL) ──────────────────────────────────
stage "Database: Neon PostgreSQL"
say "We need a PostgreSQL connection string. Neon (serverless) is recommended for dev."
say "If you already have a local PostgreSQL, you can use that instead."
open_url "https://console.neon.tech"
step "Sign in or create a Neon account"
step "Create a new project (or select existing) → copy the connection string"
step "It looks like: postgresql://user:pass@ep-xxx.us-east-1.aws.neon.tech/dbname?sslmode=require"
ask_secret DATABASE_URL "Paste the DATABASE_URL (connection string):"
write_env DATABASE_URL "$DATABASE_URL"
set_secret DATABASE_URL "$DATABASE_URL"

# ── Stage 2: Better Auth Secret ────────────────────────────────────────────
stage "Auth: Better Auth Secret"
say "Generate a strong random secret for Better Auth session encryption."
say "You can use: openssl rand -base64 32"
note "Run this in another terminal if you want:  openssl rand -base64 32"
ask_secret BETTER_AUTH_SECRET "Paste or type the BETTER_AUTH_SECRET (min 32 chars):"
write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
set_secret BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"

say "Now set the app URL (used by Better Auth and client)."
ask NEXT_PUBLIC_APP_URL "NEXT_PUBLIC_APP_URL [http://localhost:3000]:" "http://localhost:3000"
write_env NEXT_PUBLIC_APP_URL "$NEXT_PUBLIC_APP_URL"
set_var NEXT_PUBLIC_APP_URL "$NEXT_PUBLIC_APP_URL"

say "Optional: BETTER_AUTH_URL (defaults to NEXT_PUBLIC_APP_URL in dev)."
ask BETTER_AUTH_URL "BETTER_AUTH_URL [Enter to skip]:" ""
if [[ -n "$BETTER_AUTH_URL" ]]; then
  write_env BETTER_AUTH_URL "$BETTER_AUTH_URL"
  set_secret BETTER_AUTH_URL "$BETTER_AUTH_URL"
fi

# ── Stage 3: Admin Bootstrap ───────────────────────────────────────────────
stage "Admin: Bootstrap Super Admin"
say "Create the first super-admin account. This runs 'npm run admin:bootstrap' later."
ask ADMIN_EMAIL "Admin email:"
ask_secret ADMIN_PASSWORD "Admin password (min 8 chars):"
write_env ADMIN_EMAIL "$ADMIN_EMAIL"
write_env ADMIN_PASSWORD "$ADMIN_PASSWORD"
set_secret ADMIN_EMAIL "$ADMIN_EMAIL"
set_secret ADMIN_PASSWORD "$ADMIN_PASSWORD"

# ── Stage 4: Vercel Blob Storage (optional) ────────────────────────────────
stage "Storage: Vercel Blob (optional)"
say "Vercel Blob provides file upload/storage. Skip if not needed."
if confirm "Do you want to configure Vercel Blob?"; then
  open_url "https://vercel.com/dashboard/stores"
  step "Create a new Blob store or select existing"
  step "Go to Settings → Tokens → Create a Read/Write token"
  ask_secret BLOB_READ_WRITE_TOKEN "Paste the BLOB_READ_WRITE_TOKEN:"
  write_env BLOB_READ_WRITE_TOKEN "$BLOB_READ_WRITE_TOKEN"
  set_secret BLOB_READ_WRITE_TOKEN "$BLOB_READ_WRITE_TOKEN"
else
  note "Skipped Vercel Blob."
fi

# ── Stage 5: Google Integration (optional, advanced) ───────────────────────
stage "Google: Service Account + OAuth (optional)"
say "This enables Google Sheets sync (secretariat/falak) and Google Drive uploads."
say "Requires a Google Cloud project with Sheets API + Drive API enabled."
if confirm "Do you want to configure Google integration?"; then
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Create a Service Account (or select existing)"
  step "Grant roles: Editor (or custom: Sheets + Drive)"
  step "Create and download JSON key"
  step "Open the JSON file and copy 'client_email' and 'private_key'"
  ask GOOGLE_SERVICE_ACCOUNT_EMAIL "Paste the service account email:"
  say "For the private key, paste the ENTIRE value including -----BEGIN PRIVATE KEY-----"
  say "The wizard will handle newlines automatically."
  ask_secret GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY "Paste the private key:"
  write_env GOOGLE_SERVICE_ACCOUNT_EMAIL "$GOOGLE_SERVICE_ACCOUNT_EMAIL"
  write_env GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY "$GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY"
  set_secret GOOGLE_SERVICE_ACCOUNT_EMAIL "$GOOGLE_SERVICE_ACCOUNT_EMAIL"
  set_secret GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY "$GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY"

  say "Optional: organization emails to share spreadsheets with (comma-separated)."
  ask GOOGLE_ORGANIZATION_EMAILS "Emails to share with [Enter to skip]:" ""
  if [[ -n "$GOOGLE_ORGANIZATION_EMAILS" ]]; then
    write_env GOOGLE_ORGANIZATION_EMAILS "$GOOGLE_ORGANIZATION_EMAILS"
    set_var GOOGLE_ORGANIZATION_EMAILS "$GOOGLE_ORGANIZATION_EMAILS"
  fi

  say "For Google Drive uploads, you also need OAuth Client ID/Secret."
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Create OAuth 2.0 Client ID (Web application type)"
  step "Authorized redirect URI: https://your-domain/api/admin/google-drive/callback"
  step "Copy Client ID and Client Secret"
  ask GOOGLE_CLIENT_ID "Paste Google Client ID [Enter to skip]:" ""
  if [[ -n "$GOOGLE_CLIENT_ID" ]]; then
    ask_secret GOOGLE_CLIENT_SECRET "Paste Google Client Secret:"
    write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
    write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
    set_secret GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
    set_secret GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
  fi

  say "After this wizard, run: npm run setup:google"
  say "It will create the spreadsheets and output GOOGLE_SPREADSHEET_PENDATAAN_ID and GOOGLE_SPREADSHEET_FALAK_ID"
  say "Add those to .env and GitHub secrets manually."
else
  note "Skipped Google integration."
fi

# ── Stage 6: Cron Secret (optional) ────────────────────────────────────────
stage "Cron: CRON_SECRET (optional)"
say "Used to secure cron endpoints (e.g., reporting sync)."
if confirm "Do you want to set a CRON_SECRET?"; then
  note "Generate with: openssl rand -base64 32"
  ask_secret CRON_SECRET "Paste or type the CRON_SECRET:"
  write_env CRON_SECRET "$CRON_SECRET"
  set_secret CRON_SECRET "$CRON_SECRET"
else
  note "Skipped CRON_SECRET."
fi

# ── Stage 7: Finalize & Next Steps ─────────────────────────────────────────
stage "Finalize"
say "All captured values written to $ENV_FILE and GitHub secrets (where gh is available)."
say "Next steps:"
note "  1. Run: npm install"
note "  2. Run: npm run prisma:generate"
note "  3. Run: npm run prisma:migrate  (or: npm run db:push)"
note "  4. Run: npm run admin:bootstrap"
note "  5. Run: npm run dev"
if [[ -n "${GOOGLE_SERVICE_ACCOUNT_EMAIL:-}" ]]; then
  note "  6. Run: npm run setup:google  (then add the two spreadsheet IDs to .env + GitHub secrets)"
fi
say "Verify: npm run check"

finish
}

run_wizard "$@"; exit